def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]
    seen = set()
    rectangles = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            ys = [y for y, x in cells]
            xs = [x for y, x in cells]
            y0, y1, x0, x1 = min(ys), max(ys), min(xs), max(xs)
            area = (y1-y0+1) * (x1-x0+1)
            if area >= 4 and len(cells) / area >= 0.65:
                rectangles.append((y0, y1, x0, x1, color))

    # Clear stray marks, then restore the solid colored rectangles.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                out[r][c] = bg
    for y0, y1, x0, x1, color in rectangles:
        for r in range(y0, y1+1):
            for c in range(x0, x1+1):
                out[r][c] = color
    return out
